// WrongGPU launcher core: the embedded payload and the program's own resources (generated by tools/make_payload.py).
// Written for this project.
#include "payload.h"

namespace wg {

// ------------------------------------------------------------------------------------------------
// Embedded payload and converter map (resources generated by tools/make_payload.py)
// ------------------------------------------------------------------------------------------------
const void* ResourceData(int id, DWORD& size) {
    HRSRC r = FindResourceW(nullptr, MAKEINTRESOURCEW(id), MAKEINTRESOURCEW(10) /* RT_RCDATA */);
    if (!r) { size = 0; return nullptr; }
    HGLOBAL h = LoadResource(nullptr, r);
    size = SizeofResource(nullptr, r);
    return h ? LockResource(h) : nullptr;
}
const void* PayloadData(const PayloadFile& f, DWORD& size) { return ResourceData(f.id, size); }
size_t PayloadCount(Context& ctx) { return ctx.data->count; }
unsigned long long PayloadBytes(Context& ctx) { unsigned long long n = 0; for (auto& f : *ctx.data) n += f.size; return n; }
bool PayloadHas(Context& ctx, const wchar_t* rel) { for (auto& f : *ctx.data) if (IEq(f.rel, rel)) return true; return false; }

}  // namespace wg
